<?php

declare(strict_types=1);

$taskStates = ['assigned' => 'Asignada', 'submitted' => 'Pendiente de validación', 'approved' => 'Validada', 'cancelled' => 'Cancelada'];
$casePath = $user->roleCode === 'csi_manager' ? '/csi/requests/' : '/technician/requests/';
$caseFinished = in_array($request['status_code'] ?? null, ['resolved', 'closed', 'cancelled'], true);
$canDelegateCase = $user->can('request.delegate') && (
    $user->roleCode === 'csi_manager' ? ($request['technician_id'] ?? null) !== null : (int) ($request['technician_id'] ?? $user->id) === $user->id
) && !$caseFinished;
?>
<section class="mt-6 rounded-2xl border border-slate-200 bg-white p-6 shadow-card" aria-labelledby="tareas-colaboracion"><h2 id="tareas-colaboracion" class="text-xl font-bold">Colaboración en la atención</h2><p class="mt-2 text-sm text-slate-600">El responsable asignado conserva el caso. Las tareas de practicantes requieren validación antes de cerrar la atención.</p>
<?php if ($caseTasks === []): ?><p class="mt-4 text-slate-600">Aún no hay tareas delegadas.</p><?php else: ?><ol class="mt-5 space-y-4"><?php foreach ($caseTasks as $task): ?><li class="rounded-xl border border-slate-200 p-4"><div class="flex flex-wrap items-center justify-between gap-2"><h3 class="font-bold"><?= $e($task['intern_name']) ?></h3><span class="rounded-full bg-slate-100 px-3 py-1 text-xs font-semibold"><?= $e($taskStates[$task['state']] ?? $task['state']) ?></span></div><p class="mt-2 whitespace-pre-wrap break-words text-sm text-slate-700"><?= $e($task['instructions']) ?></p><?php if ($task['work_note'] !== null): ?><p class="mt-3 whitespace-pre-wrap break-words rounded-lg bg-institutional-50 p-3 text-sm"><?= $e($task['work_note']) ?></p><?php endif; ?><p class="mt-3 text-xs text-slate-600">Responsable: <?= $e($task['responsible_name']) ?><?php if ($task['validator_name'] !== null): ?> · Validó: <?= $e($task['validator_name']) ?><?php endif; ?></p><?php if (!$caseFinished && $task['state'] === 'submitted' && ($user->roleCode === 'csi_manager' || $user->id === (int) ($request['technician_id'] ?? $user->id))): ?><form method="post" action="/technician/tasks/<?= (int) $task['id'] ?>/approve" class="mt-3"><input type="hidden" name="_csrf" value="<?= $e($session->csrfToken()) ?>"><button class="min-h-11 rounded-lg bg-institutional-700 px-4 text-sm font-bold text-white hover:bg-institutional-800">Validar trabajo</button></form><?php endif; ?><?php if (!$caseFinished && in_array($task['state'], ['assigned', 'submitted'], true) && ($user->roleCode === 'csi_manager' || $user->id === (int) ($request['technician_id'] ?? $user->id))): ?><form method="post" action="/technician/tasks/<?= (int) $task['id'] ?>/cancel" class="mt-2"><input type="hidden" name="_csrf" value="<?= $e($session->csrfToken()) ?>"><button class="min-h-11 rounded-lg border border-slate-300 px-4 text-sm font-semibold text-slate-700 hover:bg-slate-50">Cancelar tarea</button></form><?php endif; ?></li><?php endforeach; ?></ol><?php endif; ?>
<?php if ($canDelegateCase): ?><div class="mt-6 border-t border-slate-200 pt-5"><h3 class="font-bold">Delegar tarea a practicante</h3><?php if (isset($formErrors['delegate']) || isset($formErrors['intern']) || isset($formErrors['instructions'])): ?><p role="alert" class="mt-3 rounded-lg bg-rose-50 p-3 text-sm text-rose-900"><?= $e(implode(' ', $formErrors)) ?></p><?php endif; ?><?php if ($interns === []): ?><p class="mt-3 text-sm text-slate-600">No hay practicantes activos. Crea una cuenta solo si necesitan usar el sistema.</p><?php else: ?><form method="post" action="<?= $casePath . $e($request['public_code']) ?>/delegate" class="mt-4 space-y-4"><input type="hidden" name="_csrf" value="<?= $e($session->csrfToken()) ?>"><div><label for="intern" class="block text-sm font-semibold">Practicante</label><select id="intern" name="intern" required class="mt-2 min-h-11 w-full rounded-lg border border-slate-300 px-3"><option value="">Selecciona un practicante</option><?php foreach ($interns as $intern): ?><option value="<?= (int) $intern['id'] ?>"><?= $e($intern['name']) ?></option><?php endforeach; ?></select></div><div><label for="instructions" class="block text-sm font-semibold">Instrucciones</label><textarea id="instructions" name="instructions" required minlength="5" maxlength="2000" rows="3" class="mt-2 w-full rounded-lg border border-slate-300 p-3 focus-visible:ring-2 focus-visible:ring-institutional-700"></textarea></div><button class="min-h-11 rounded-lg border border-institutional-700 px-4 font-bold text-institutional-700 hover:bg-institutional-50">Delegar tarea</button></form><?php endif; ?></div><?php endif; ?></section>
